import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        return v.strip()
    return v

def to_number(v):
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if s.endswith("%"):
            try:
                return float(s[:-1]) / 100.0
            except ValueError:
                return v
        try:
            return float(s)
        except ValueError:
            return v
    return v

# Representative and percentage columns in the source table:
# F/H, I/K, L/N, O/Q, R/T
rep_cols = [6, 9, 12, 15, 18]
pct_cols = [8, 11, 14, 17, 20]

lookup = {}

for r in range(5, vws.max_row + 1):
    client = clean(vws.cell(row=r, column=3).value)
    if client is None:
        continue

    for rc, pc in zip(rep_cols, pct_cols):
        rep = clean(vws.cell(row=r, column=rc).value)
        pct = vws.cell(row=r, column=pc).value

        if rep is not None and pct is not None:
            lookup[(str(client), str(rep))] = to_number(pct)

for r in range(21, 24):
    rep = clean(ws.cell(row=r, column=2).value)
    client = clean(ws.cell(row=r, column=3).value)

    if rep is None or client is None:
        result = None
    else:
        result = lookup.get((str(client), str(rep)))

    ws.cell(row=r, column=4).value = result
    print(f"Row {r}: {rep!r} / {client!r} -> {result!r}")

wb.save(OUT)
